import assert from 'node:assert/strict'
import {readFileSync} from 'node:fs'
const ui=readFileSync('src/features/orders/OrderCatalogResolutionModal.tsx','utf8')
const server=readFileSync('worker/domains/catalog.ts','utf8')
const ctx=readFileSync('worker/domains/catalog-review.ts','utf8')
assert(ui.includes("context?.product?.genderScope === 'female' ? 'ЖЕН'"))
assert(ui.includes("context?.product?.genderScope === 'male' ? 'МУЖ'"))
assert(ui.includes('const genderScopeConflict = Boolean('))
assert(ui.includes('if (genderScopeConflict) {'))
assert(ui.includes('Пол изделия в заказе не совпадает с назначением товара.'))
assert(ui.includes('Проверяемые характеристики'))
assert(!ui.includes("context.product ? 'В каталоге'"),'A draft is not an existing catalog SKU')
assert(server.includes('assertCatalogGenderAllowedForScope('))
assert(ctx.includes('assertCatalogGenderAllowedForScope(requestedGenderScope'))
const validate=(scope,gender)=>Boolean((scope==='female'||scope==='male')&&gender!==(scope==='female'?'ЖЕН':'МУЖ'))
assert(validate('female','МУЖ'))
assert(validate('male','ЖЕН'))
assert(!validate('female','ЖЕН'))
assert(!validate('unisex','МУЖ'))
console.log('RESOLVER_MASTER_PRODUCT_GENDER_CONFLICT_BLOCKED_BEFORE_SAVE_PASSED')
